begin;
\ir fixtures/clinical.sql
reset role;
update public.locations set timezone=case when extract(hour from clock_timestamp()at time zone'Etc/UTC')>=12 then'Etc/GMT+12'else'Etc/UTC'end,version=version+1 where id=pg_temp.location();
create function pg_temp.reception_day()returns date language sql as $$select(clock_timestamp()at time zone timezone)::date from public.locations where id=pg_temp.location()$$;
create function pg_temp.reception_time(day_offset integer,minute integer)returns timestamptz language sql as $$select((pg_temp.reception_day()+day_offset)::timestamp at time zone timezone)+make_interval(mins=>minute)from public.locations where id=pg_temp.location()$$;
insert into public.appointments(id,practice_id,location_id,doctor_user_id,patient_id,starts_at,ends_at,timezone,location_name,state,created_by)
 select pg_temp.id(n),pg_temp.practice(),pg_temp.location(),pg_temp.id(1),pg_temp.patient(),pg_temp.reception_time(d,m),pg_temp.reception_time(d,m+10),l.timezone,l.name,state,pg_temp.id(1)
 from(values(800,0,0,'booked'),(801,0,20,'booked'),(802,-1,0,'no_show'),(803,-1,0,'booked'),(804,1,0,'booked'))v(n,d,m,state)cross join public.locations l where l.id=pg_temp.location();
create function pg_temp.reception(action text,n integer,ver integer,k integer,reason text default 'Synthetic explicit reception reason')returns jsonb language sql as $$select public.doctor_reception_command(pg_temp.practice(),pg_temp.location(),pg_temp.id(n),ver,action,jsonb_build_object('reason',reason),pg_temp.id(k))$$;
create function pg_temp.reception_snapshot(n integer)returns jsonb language sql security definer set search_path=''as $$select to_jsonb(a)from public.appointments a where id=pg_temp.id(n)$$;
set local role authenticated;select pg_temp.claim(1);
select public.doctor_write_schedule(pg_temp.practice(),pg_temp.location(),0,jsonb_build_object('slot_minutes',10,'weekly',(select jsonb_agg(jsonb_build_object('weekday',d,'start',0,'end',1440))from generate_series(0,6)d),'exceptions','[]'::jsonb),pg_temp.id(810),2);
select public.doctor_transition_appointment(pg_temp.practice(),pg_temp.location(),pg_temp.id(801),1,'checked_in','',pg_temp.id(811));
select is(pg_temp.reception('late_check_in',800,1,812)->>'state','checked_in','DOS-M3-003-C01: explicit late arrival enters queue');
select is(pg_temp.reception('late_check_in',800,1,812)->>'version','2','exact check-in retry returns one receipt');
select throws_ok($$select pg_temp.reception('late_check_in',800,1,813)$$,'40001','DOCTOR_APPOINTMENT_CONFLICT','a second intent cannot double check in');
select throws_ok($$select pg_temp.reception('late_check_in',800,1,812,'Changed reason')$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','receipt material cannot change');
select is(public.doctor_appointment_board(pg_temp.practice(),pg_temp.location(),pg_temp.reception_day())->>'queue_total','2','double retries do not duplicate queue entries');
select is(public.doctor_appointment_board(pg_temp.practice(),pg_temp.location(),pg_temp.reception_day())#>>'{queue,0,id}',pg_temp.id(801)::text,'queue starts in recorded arrival order');
select pg_temp.put('arrival',pg_temp.reception_snapshot(801)->'checked_in_at');
select is(pg_temp.reception('move_to_end',801,2,814)->>'queue_order','administrative_only','DOS-M3-003-C02: order is explicitly administrative');
select is(public.doctor_appointment_board(pg_temp.practice(),pg_temp.location(),pg_temp.reception_day())#>>'{queue,0,id}',pg_temp.id(800)::text,'authoritative queue reorders before pagination');
select is(pg_temp.reception_snapshot(801)->'checked_in_at',pg_temp.v('arrival'),'manual order preserves real arrival timestamp');
select throws_ok($$select pg_temp.reception('move_to_end',801,2,815)$$,'40001','DOCTOR_APPOINTMENT_CONFLICT','stale reorder rejected');
select throws_ok($$select pg_temp.reception('late_check_in',804,1,816)$$,'22023','DOCTOR_RECEPTION_TRANSITION_DENIED','future-day late arrival refused');
select throws_ok($$select pg_temp.reception('reverse_no_show',802,1,817)$$,'40001','DOCTOR_APPOINTMENT_CONFLICT','no-show reversal cannot consume an occupied commitment');
select is(pg_temp.reception_snapshot(802)->>'state','no_show','conflict rolls back original no-show');
select public.doctor_transition_appointment(pg_temp.practice(),pg_temp.location(),pg_temp.id(803),1,'cancelled','Synthetic release conflicting commitment',pg_temp.id(818));
select is(pg_temp.reception('reverse_no_show',802,1,819)->>'state','booked','no-show reverses explicitly once original capacity is free');
select is(pg_temp.reception('queue_exit',800,2,820)->>'state','cancelled','explicit exit removes waiting appointment');
select is(public.doctor_appointment_board(pg_temp.practice(),pg_temp.location(),pg_temp.reception_day())->>'queue_total','1','exited appointment is absent from active queue');
select public.doctor_transition_appointment(pg_temp.practice(),pg_temp.location(),pg_temp.id(801),3,'in_progress','',pg_temp.id(821));
select throws_ok($$select pg_temp.reception('queue_exit',801,4,822)$$,'22023','DOCTOR_RECEPTION_TRANSITION_DENIED','reception cannot exit an in-progress visit');
select throws_ok($$select pg_temp.reception('move_to_end',801,4,823,'')$$,'22023','DOCTOR_APPOINTMENT_REASON_REQUIRED','every exception requires an explicit reason');
select pg_temp.claim(2);
select throws_ok($$select pg_temp.reception('reverse_no_show',802,1,819)$$,'42501','DOCTOR_ACCESS_DENIED','foreign owner cannot replay another practice receipt');
select pg_temp.claim(3);
select throws_ok($$select pg_temp.reception('move_to_end',801,4,824)$$,'42501','DOCTOR_ACCESS_DENIED','patients-only secretary has no queue authority');
select pg_temp.claim(1);
select pg_temp.put('walk',jsonb_build_object('patient_id',pg_temp.patient(),'day',pg_temp.reception_day(),'minute',(extract(hour from clock_timestamp()at time zone l.timezone)::integer*60+floor(extract(minute from clock_timestamp()at time zone l.timezone)/10)::integer*10)+60,'schedule_version',1,'location_version',2,'type_id',null,'type_version',null,'reason','Synthetic walk-in requested by operator'))from public.locations l where id=pg_temp.location();
select pg_temp.put('walk_result',public.doctor_reception_command(pg_temp.practice(),pg_temp.location(),null,0,'walk_in',pg_temp.v('walk'),pg_temp.id(825)));
select is(pg_temp.v('walk_result')->>'state','checked_in','manual walk-in books and checks in atomically');
select is(public.doctor_reception_command(pg_temp.practice(),pg_temp.location(),null,0,'walk_in',pg_temp.v('walk'),pg_temp.id(825))->>'appointment_id',pg_temp.v('walk_result')->>'appointment_id','walk-in replay creates no second appointment');
select is((public.doctor_patients(pg_temp.practice(),pg_temp.location())->>'total')::integer,1,'walk-in never creates or merges a patient identity');
select throws_ok($$select public.doctor_reception_command(pg_temp.practice(),pg_temp.location(),null,0,'walk_in',pg_temp.v('walk')||jsonb_build_object('day',pg_temp.reception_day()+1),pg_temp.id(826))$$,'22023','DOCTOR_RECEPTION_SAME_DAY_REQUIRED','walk-in cannot silently choose a future day');
select is((public.doctor_appointment_history(pg_temp.practice(),pg_temp.location(),(pg_temp.v('walk_result')->>'appointment_id')::uuid)->>'total')::integer,3,'walk-in retains booking, check-in and attributed exception history');
select is(public.doctor_appointment_history(pg_temp.practice(),pg_temp.location(),pg_temp.id(800))#>>'{events,0,type}','appointment.reception.queue_exit','exception history is readable through authoritative appointment contract');
reset role;
select is((select count(*)::integer from public.appointment_events where event_type like'appointment.reception.%'and details->>'reason'='Synthetic explicit reception reason'),4,'all successful exceptions retain explicit reason and actor');
select is((select count(*)::integer from doctor_private.command_receipts where command_key in(pg_temp.id(813),pg_temp.id(815),pg_temp.id(817),pg_temp.id(822),pg_temp.id(824),pg_temp.id(826))),0,'denied/conflicting operations leave no receipt');
select * from finish();rollback;
